def compute(vars):
    net_income = vars["Net Income"]
    total_assets = vars["Total Assets"]
    multiplier = vars["100"]

    if total_assets == 0:
        return None

    roa = (net_income / total_assets) * multiplier
    return {
        "value": roa,
        "trace": {
            "Net Income": net_income,
            "Total Assets": total_assets,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
